  "terrain_grid": "china_coarse",
  "lead": "康熙十二年（1673）撤藩令下，吴三桂杀云南巡抚朱国治起兵，称天下都招讨兵马大元帅；耿精忠据闽、尚之信据粤，三藩连横，清廷云贵闽粤湘川一时尽失。康熙调度平叛，1676 耿降、1679 尚降、湖南四川次第收复，1681 清军入昆明、吴世璠自杀，三藩平。实控区随事件年份由清据全域翻为三藩据西南东南、终复归清。",
